def func(text: str = '', pmid: str = '', entities=None):
    pt = get_plugin('PubTatorRelationExtractor')
    if not pt:
        return {'relations': [], 'raw_relations': [], 'error': 'PubTatorRelationExtractor plugin unavailable'}
    try:
        return pt.extract_relations(text=text or '', pmid=pmid or '', entities=entities)
    except Exception as ex:
        return {'relations': [], 'raw_relations': [], 'error': str(ex)}
